#!/usr/bin/env bash
# Prints .dependency-footprint: for each package a consumer can import, every
# package outside the standard library and this module that it compiles in.
#
#   .github/dependency-footprint.sh > .dependency-footprint
#
# CI fails when the committed file differs from this output. The point is the
# indirect half: depguard sees only this module's own imports, so an upgrade of
# a dependency that starts pulling in a new package changes nothing it checks.
# Here it changes a line, and the change is reviewed with the upgrade.
set -euo pipefail

# The set depends on the platform (golang.org/x/sys/unix is linux's, windows
# gets x/sys/windows), so the file is always computed for one: CI's.
export GOOS=linux GOARCH=amd64 CGO_ENABLED=0

module=$(go list -m)
cat <<'HEADER'
# Packages compiled into each importable package, outside the standard library
# and this module. Generated by .github/dependency-footprint.sh; regenerate
# with `.github/dependency-footprint.sh > .dependency-footprint` and review the
# diff: every added line is code every consumer of that package now builds.
# A package absent from this list compiles nothing outside the standard library.
HEADER
for pkg in $(go list ./... | grep -v "^${module}/examples/"); do
  rel=${pkg#"$module"}
  rel=${rel#/}
  go list -deps -f '{{if not .Standard}}{{.ImportPath}}{{end}}' "$pkg" |
    { grep -v "^${module}\(/\|$\)" || true; } |
    sed "s|^|${rel:-.} |"
done | LC_ALL=C sort
